<script setup lang="ts">
import { reactive,ref } from 'vue';
import { useTheme } from 'vuetify';
import { useAuth } from '../stores/auth';
import { useUi } from '../stores/ui';
import { api } from '../services/api';
const auth=useAuth(),ui=useUi(),theme=useTheme(),profile=reactive({name:auth.user?.name||'',email:auth.user?.email||''}),password=reactive({current_password:'',password:'',password_confirmation:''}),saving=ref(false),changing=ref(false);
async function save(){saving.value=true;try{auth.user=(await api.put('/profile',profile)).data.data;ui.notify('Profils atjaunināts.');}catch(e){ui.fail(e);}finally{saving.value=false;}}
async function change(){changing.value=true;try{await api.put('/profile/password',password);Object.assign(password,{current_password:'',password:'',password_confirmation:''});ui.notify('Parole mainīta. Citas sesijas ir izbeigtas.');}catch(e){ui.fail(e);}finally{changing.value=false;}}
function setTheme(value:string){theme.change(value);localStorage.setItem('taskflow-theme',value);}
</script>
<template><div class="page-heading"><div><div class="eyebrow">PIELĀGO SAVU DARBA VIETU</div><h1>Iestatījumi</h1><p>Tavs profils, drošība un izskats.</p></div></div><div class="settings-grid"><v-card class="pa-7"><h2 class="mb-1">Mans profils</h2><p class="text-medium-emphasis mb-6">Informācija, ko redz tava komanda.</p><form @submit.prevent="save"><v-text-field v-model="profile.name" label="Vārds un uzvārds" required maxlength="100"/><v-text-field v-model="profile.email" label="E-pasts" type="email" required maxlength="254"/><v-btn color="primary" type="submit" :loading="saving">Saglabāt izmaiņas</v-btn></form></v-card><v-card class="pa-7"><h2 class="mb-1">Izskats</h2><p class="text-medium-emphasis mb-6">Izvēlies sev ērtāko darba vidi.</p><div class="theme-options"><button :class="{selected:!theme.global.current.value.dark}" @click="setTheme('light')"><div class="theme-preview light-preview"><i/><i/><i/></div><v-icon icon="mdi-weather-sunny" size="18"/> Gaišs</button><button :class="{selected:theme.global.current.value.dark}" @click="setTheme('dark')"><div class="theme-preview dark-preview"><i/><i/><i/></div><v-icon icon="mdi-weather-night" size="18"/> Tumšs</button></div><p class="text-caption text-medium-emphasis mt-5">Izvēle tiek saglabāta šajā pārlūkā.</p></v-card><v-card class="pa-7"><h2 class="mb-1">Mainīt paroli</h2><p class="text-medium-emphasis mb-6">Izmanto vismaz 8 rakstzīmes. Pēc maiņas citas sesijas tiks izbeigtas.</p><form @submit.prevent="change"><v-text-field v-model="password.current_password" label="Pašreizējā parole" type="password" autocomplete="current-password" required/><v-text-field v-model="password.password" label="Jaunā parole" type="password" autocomplete="new-password" required minlength="8"/><v-text-field v-model="password.password_confirmation" label="Atkārtota jaunā parole" type="password" autocomplete="new-password" required/><v-btn color="primary" type="submit" :loading="changing">Mainīt paroli</v-btn></form></v-card></div></template>

